        <<abstract>>
        +eseguiAccesso(Cliente c) boolean
        #verificaBadge(Cliente c) boolean*
        #calcolaCosto(Cliente c) double*
        #addebita(Cliente c, double importo) void
        #registraIngresso(Cliente c) void
        #servizioExtra(Cliente c) boolean
    }
    class AccessoAbbonato {
        #verificaBadge(Cliente c) boolean
        #calcolaCosto(Cliente c) double
    }
    class AccessoOccasionale {
