    }
    Accesso <|-- AccessoAbbonato
    Accesso <|-- AccessoOccasionale
```

## Codice Java completo

```java
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

public class Cliente {
    private final String nome;
    private double credito;
    private final LocalDate scadenzaAbbonamento;   // null se non abbonato
    private final boolean vuoleSauna;
    public Cliente(String nome, double credito, LocalDate scadenza, boolean sauna) {
        this.nome = nome; this.credito = credito; this.scadenzaAbbonamento = scadenza; this.vuoleSauna = sauna;
    }
    public String getNome() { return nome; }
    public double getCredito() { return credito; }
    public void scala(double importo) { credito -= importo; }
    public LocalDate getScadenza() { return scadenzaAbbonamento; }
    public boolean vuoleSauna() { return vuoleSauna; }
}

public abstract class Accesso {
    protected final List<String> registro = new ArrayList<>();

    // TEMPLATE METHOD: sequenza fissa, final per impedirne la modifica
    public final boolean eseguiAccesso(Cliente c) {
        if (!verificaBadge(c)) return false;
        double costo = calcolaCosto(c);
        if (servizioExtra(c)) costo += 5.0;          // hook
        addebita(c, costo);
        registraIngresso(c);
        return true;
    }

    protected abstract boolean verificaBadge(Cliente c);   // passo obbligatorio
    protected abstract double calcolaCosto(Cliente c);     // passo obbligatorio

    protected boolean servizioExtra(Cliente c) { return false; }  // HOOK: default "nessun extra"

    protected void addebita(Cliente c, double importo) {   // passo comune
        if (importo > 0) c.scala(importo);
    }
    protected void registraIngresso(Cliente c) {           // passo comune
        registro.add(c.getNome());
    }
}

public class AccessoAbbonato extends Accesso {
    @Override protected boolean verificaBadge(Cliente c) {
        return c.getScadenza() != null && !c.getScadenza().isBefore(LocalDate.now());
    }
    @Override protected double calcolaCosto(Cliente c) { return 0.0; }
}

public class AccessoOccasionale extends Accesso {
    private static final double TARIFFA = 7.0;
    @Override protected boolean verificaBadge(Cliente c) { return c.getCredito() >= TARIFFA; }
    @Override protected double calcolaCosto(Cliente c) { return TARIFFA; }
    @Override protected boolean servizioExtra(Cliente c) { return c.vuoleSauna(); } // usa l'hook
}

public class Main {
    public static void main(String[] args) {
        Cliente anna = new Cliente("Anna", 20.0, null, true);
        Accesso a = new AccessoOccasionale();
        System.out.println(a.eseguiAccesso(anna) + " credito=" + anna.getCredito()); // true credito=8.0
    }
}
```

